INSERT INTO "Question" ("id", "sourceId", "questionEn", "questionFr", "answersEn", "answersFr", "correctIndex", "category", "difficulty", "createdAt") VALUES
    (gen_random_uuid()::text, 'gen-2bb829574ddab927', 'Akira Kurosawa was born in the city of Osaka.', 'Akira Kurosawa est né dans la ville d''Osaka.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b546dadac36137c5', 'What profession did Akira Kurosawa''s brother, Heigo, practice in Tokyo theaters?', 'Quelle profession le frère d''Akira Kurosawa, Heigo, exerçait-il dans les cinémas de Tokyo ?', '["Benshi", "Kendo master", "Painter", "Film producer"]'::jsonb, '["Benshi", "Maître de kendo", "Peintre", "Producteur de cinéma"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-ba5902ff816d8e6c', 'At what age did Akira Kurosawa begin his career at the P.C.L. studio?', 'À quel âge Akira Kurosawa a-t-il commencé sa carrière au studio P.C.L. ?', '["33", "21", "25", "30"]'::jsonb, '["33", "21", "25", "30"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a1cacb61d187ee27', 'Which director acted as a mentor to Akira Kurosawa during his early years as an assistant?', 'Quel réalisateur a été le mentor d''Akira Kurosawa durant ses premières années d''assistant ?', '["Yasujirō Ozu", "Satsuo Yamamoto", "Ken''ichi Enomoto", "Kajirō Yamamoto"]'::jsonb, '["Yasujirō Ozu", "Satsuo Yamamoto", "Ken''ichi Enomoto", "Kajirō Yamamoto"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-839e32873ced54ab', 'Akira Kurosawa''s directorial debut, Sanshiro Sugata, was a failure upon its release.', 'Le premier film d''Akira Kurosawa, La Légende du grand judo, fut un échec à sa sortie.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9bb77a05d6d633dc', 'Who was the actress that Akira Kurosawa married in 1945?', 'Quelle actrice Akira Kurosawa a-t-il épousée en 1945 ?', '["Yōko Yaguchi", "Kazuko Kurosawa", "Hisao Kurosawa", "Tsuneo Tomita"]'::jsonb, '["Yōko Yaguchi", "Kazuko Kurosawa", "Hisao Kurosawa", "Tsuneo Tomita"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-4e4efcf0cf67ab80', 'Director Yasujirō Ozu helped get Akira Kurosawa''s debut film approved by censors.', 'Le réalisateur Yasujirō Ozu a aidé à faire approuver le premier film d''Akira Kurosawa par la censure.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-5e69dd8cce240c12', 'On which traditional Japanese theatrical form is the film ''The Men Who Tread on the Tiger''s Tail'' based?', 'Sur quelle forme théâtrale traditionnelle japonaise est basé le film ''Les Hommes qui marchèrent sur la queue du tigre'' ?', '["Kabuki", "Noh", "Kyōgen", "Bunraku"]'::jsonb, '["Kabuki", "Noh", "Kyōgen", "Bunraku"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-16243e7df84324da', 'Quentin Tarantino was born in Los Angeles, California.', 'Quentin Tarantino est né à Los Angeles, en Californie.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3f31ebfbd0590a1b', 'Which subject did Christopher Nolan study at University College London?', 'Quelle matière Christopher Nolan a-t-il étudiée à l''University College London ?', '["Film studies", "History", "English literature", "Advertising"]'::jsonb, '["Études cinématographiques", "Histoire", "Littérature anglaise", "Publicité"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b369b604e035ff2b', 'What materials did a young Christopher Nolan use to build his early film sets?', 'Quels matériaux le jeune Christopher Nolan utilisait-il pour construire ses décors de films ?', '["Plastic, glass, sand and wire", "Paper, ink, paint and cardboard", "Clay, flour, egg boxes and toilet rolls", "Wood, metal, glue and tape"]'::jsonb, '["Plastique, verre, sable et fil de fer", "Papier, encre, peinture et carton", "Argile, farine, boîtes à œufs et rouleaux de papier toilette", "Bois, métal, colle et ruban adhésif"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-55dc5b1ae6054993', 'What was the title of the surreal 8 mm film co-directed by Christopher Nolan in 1989?', 'Quel est le titre du film surréaliste en 8 mm co-réalisé par Christopher Nolan en 1989 ?', '["Space Wars", "Tarantella", "Memento", "Following"]'::jsonb, '["Space Wars", "Tarantella", "Memento", "Following"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-071e8cbfcbbea0cd', 'Christopher Nolan was accepted into a prestigious film school before attending University College London.', 'Christopher Nolan a été admis dans une école de cinéma prestigieuse avant de rejoindre l''University College London.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2ae454dc942eb4a6', 'In Christopher Nolan''s 1997 short film ''Doodlebug'', what does the protagonist discover he is actually chasing?', 'Dans le court-métrage ''Doodlebug'' de Christopher Nolan (1997), que découvre le protagoniste en poursuivant l''insecte ?', '["An extraterrestrial entity", "A ghost from his past", "A hidden camera", "A miniature version of himself"]'::jsonb, '["Une entité extraterrestre", "Un fantôme de son passé", "Une caméra cachée", "Une version miniature de lui-même"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-49fc72d71a58c22e', 'Which philosopher''s work is compared to ''Memento'' regarding the theme of memories forming identity?', 'L''œuvre de quel philosophe est comparée à ''Memento'' concernant le thème de la mémoire constituant l''identité ?', '["Friedrich Nietzsche", "Immanuel Kant", "René Descartes", "John Locke"]'::jsonb, '["Friedrich Nietzsche", "Immanuel Kant", "René Descartes", "John Locke"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-f9b1a6a361ae2744', 'Christopher Nolan''s short film ''Larceny'' was shot in color.', 'Le court-métrage ''Larceny'' de Christopher Nolan a été tourné en couleurs.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-406ee262f8e8cdaf', 'Why did David O. Russell physically confront Christopher Nolan at a Hollywood party in 2003?', 'Pourquoi David O. Russell a-t-il agressé physiquement Christopher Nolan lors d''une fête à Hollywood en 2003 ?', '["A disagreement over the casting of Jude Law", "A conflict over the editing of Memento", "A disagreement regarding the direction of Troy", "A dispute over the rights to a Batman script"]'::jsonb, '["Un désaccord concernant l''engagement de Jude Law", "Un conflit sur le montage du film Memento", "Un désaccord sur la réalisation du film Troie", "Un conflit sur les droits d''un scénario de Batman"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2dbb8a3c5bd92982', 'Which two actors did Martin Scorsese identify as his personal favorites during his youth?', 'Quels sont les deux acteurs que Martin Scorsese considérait comme ses favoris durant sa jeunesse ?', '["James Dean and Marlon Brando", "John Ford and Roberto Rossellini", "Sabu and Victor Mature", "Robert De Niro and Harvey Keitel"]'::jsonb, '["James Dean et Marlon Brando", "John Ford et Roberto Rossellini", "Sabu et Victor Mature", "Robert De Niro et Harvey Keitel"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-87b91423bd136cde', 'Who was the film professor at New York University that Martin Scorsese described as providing the most precious gift he ever received?', 'Quel professeur de cinéma à l''université de New York a offert à Martin Scorsese, selon ses propres mots, le cadeau le plus précieux qu''il ait jamais reçu ?', '["John Cassavetes", "Haig P. Manoogian", "Baird Bryant", "Roger Corman"]'::jsonb, '["John Cassavetes", "Haig P. Manoogian", "Baird Bryant", "Roger Corman"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-29125ddf90bf3137', 'On which short film did Martin Scorsese work for his first professional job as an assistant cameraman?', 'Sur quel court-métrage Martin Scorsese a-t-il effectué son premier travail professionnel en tant qu''assistant opérateur ?', '["It''s Not Just You, Murray!", "The Big Shave", "Smiles", "Boxcar Bertha"]'::jsonb, '["It''s Not Just You, Murray!", "The Big Shave", "Smiles", "Boxcar Bertha"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-7c111b4a9157171f', 'Which Scorsese short film was also known by the alternative title ''Viet ''67'' due to its critical view of the Vietnam War?', 'Quel court-métrage de Scorsese était également connu sous le titre alternatif « Viet ''67 » en raison de sa critique de la guerre du Vietnam ?', '["I Call First", "The Big Shave", "What''s a Nice Girl like You Doing in a Place like This?", "Who''s That Knocking at My Door"]'::jsonb, '["I Call First", "The Big Shave", "What''s a Nice Girl like You Doing in a Place like This?", "Who''s That Knocking at My Door"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e6d1f85f87bf9d6d', 'Which dance style did Charlie Chaplin perform as a member of the Eight Lancashire Lads?', 'Quel style de danse Charlie Chaplin pratiquait-il en tant que membre de la troupe Eight Lancashire Lads ?', '["Tap dancing", "Ballet", "Clog-dancing", "Waltz"]'::jsonb, '["Claquettes", "Ballet", "Clog-dancing", "Valse"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-daf264fd4692bc13', 'What was the name of the popular drunk character Chaplin played in the sketch ''Mumming Birds''?', 'Quel était le nom du personnage d''ivrogne que Chaplin jouait dans le sketch ''Mumming Birds'' ?', '["Tipsy Tramp", "Merry Drunkard", "Inebriate Swell", "Drunken Dandy"]'::jsonb, '["Vagabond éméché", "Joyeux buveur", "Inebriate Swell", "Dandy ivre"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-219ee9dca693fef3', 'What event led to Federico Fellini being permanently freed from military service during the war?', 'Quel événement a permis à Federico Fellini d''être définitivement libéré du service militaire pendant la guerre ?', '["He escaped to Sicily on a German military plane", "He was granted an exemption as a key cultural figure", "He was declared unfit due to a physical injury", "An Allied air raid destroyed his medical records"]'::jsonb, '["Il s''est échappé en Sicile dans un avion militaire allemand", "Il a obtenu une exemption en tant que figure culturelle", "Il a été déclaré inapte suite à une blessure physique", "Un raid aérien allié a détruit son dossier médical"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b474f54a7f16a5ff', 'What is the name of the industry-standard image-rendering API that Pixar implemented through its RenderMan software?', 'Quel est le nom de l''interface de programmation (API) de rendu d''image standard de l''industrie que Pixar a implémentée via son logiciel RenderMan ?', '["REYES", "Pixar-Trace", "RISpec", "CGL-API"]'::jsonb, '["REYES", "Pixar-Trace", "RISpec", "CGL-API"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9bf5dc98a109feb1', 'The alpha channel, a fundamental computer graphics technique, was invented by Edwin Catmull and Alvy Ray Smith while they worked at Lucasfilm.', 'Le canal alpha, une technique fondamentale en infographie, a été inventé par Edwin Catmull et Alvy Ray Smith lorsqu''ils travaillaient chez Lucasfilm.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a4d567d5b5b10553', 'What was John Lasseter''s official job title when he was first hired by the Lucasfilm team in 1983?', 'Quel était le titre officiel de John Lasseter lorsqu''il a été embauché par l''équipe de Lucasfilm en 1983 ?', '["Interface designer", "Animation director", "Script supervisor", "Graphics engineer"]'::jsonb, '["Concepteur d''interface", "Directeur d''animation", "Superviseur de scénario", "Ingénieur graphique"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-cdc941224db47b62', 'To which company was Nolan Bushnell''s studio Kadabrascope sold?', 'À quelle société le studio Kadabrascope de Nolan Bushnell fut-il vendu ?', '["Bally Games", "Lucasfilm", "Disney", "Apple"]'::jsonb, '["Bally Games", "Lucasfilm", "Disney", "Apple"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-fc4b238ba13665d7', 'Before becoming independent, Pixar attempted to produce a film based on the Monkey King with a Japanese publisher.', 'Avant de devenir indépendante, Pixar a tenté de produire un film sur le Roi Singe avec un éditeur japonais.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-24f95bd44a7f3246', 'Before becoming president of Studio Ghibli in 2008, Koji Hoshino held a leadership position at which company?', 'Avant de devenir président du Studio Ghibli en 2008, Koji Hoshino occupait un poste de direction dans quelle entreprise ?', '["Wild Bunch", "Polygon Pictures", "Walt Disney Japan", "Nippon Television"]'::jsonb, '["Wild Bunch", "Polygon Pictures", "Walt Disney Japan", "Nippon Television"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-de1ea51151f4471c', 'What percentage stake in Studio Ghibli did Nippon Television acquire in 2023?', 'Quelle part du capital du Studio Ghibli Nippon Television a-t-elle acquise en 2023 ?', '["25.5%", "10.8%", "42.3%", "50.0%"]'::jsonb, '["25,5 %", "10,8 %", "42,3 %", "50,0 %"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-96635ed15e7f03eb', 'Which Japanese studio distributed ''My Neighbors the Yamadas'' theatrically, unlike most other Studio Ghibli films?', 'Quel studio japonais a distribué ''Mes voisins les Yamada'' au cinéma, contrairement à la plupart des autres films du Studio Ghibli ?', '["Walt Disney Studios Japan", "Toho", "Shochiku", "Toei Company"]'::jsonb, '["Walt Disney Studios Japan", "Toho", "Shochiku", "Toei Company"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-43d5b3916d395ee9', 'Which format was exclusively released by Tokuma Shoten because it was not included in the Disney distribution deal?', 'Quel format a été exclusivement édité par Tokuma Shoten car il n''était pas inclus dans l''accord de distribution avec Disney ?', '["Blu-ray", "LaserDisc", "VHS", "DVD"]'::jsonb, '["Blu-ray", "LaserDisc", "VHS", "DVD"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3d395ab9cd40409e', 'Which company distributed the English dub of ''My Neighbor Totoro'' theatrically in the United States in 1993?', 'Quelle société a distribué le doublage anglais de ''Mon voisin Totoro'' au cinéma aux États-Unis en 1993 ?', '["Troma Films", "Walt Disney Pictures", "20th Century Fox", "New World Pictures"]'::jsonb, '["Troma Films", "Walt Disney Pictures", "20th Century Fox", "New World Pictures"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d04971e7221d1814', 'Who was the karting teammate whom Ayrton Senna respected most as a rival?', 'Quel équipier de karting Ayrton Senna considérait-il comme le rival qu''il respectait le plus ?', '["Lucio Pascal Gascon", "Chico Serra", "Martin Brundle", "Terry Fullerton"]'::jsonb, '["Lucio Pascal Gascon", "Chico Serra", "Martin Brundle", "Terry Fullerton"]'::jsonb, 3, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2e41715db178e935', 'Ayrton Senna accepted Ron Dennis''s offer to fund his British Formula 3 season unconditionally.', 'Ayrton Senna a accepté sans condition l''offre de Ron Dennis de financer sa saison de Formule 3 britannique.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e222d0f8bfd28e7f', 'When negotiating his first contract with Toleman, Ayrton Senna prioritized his salary above all other conditions.', 'Lors de la négociation de son premier contrat chez Toleman, Ayrton Senna a fait de son salaire sa priorité absolue.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-88c71cebd00e1933', 'Following the 1984 Monaco Grand Prix, Ayrton Senna was disqualified for failing to stop his car when the red flag was shown.', 'À l''issue du Grand Prix de Monaco 1984, Ayrton Senna a été disqualifié pour ne pas avoir arrêté sa monoplace sous le drapeau rouge.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a0196be590cb7934', 'In which city did Martin Fourcade achieve his first top-ten finish in a World Cup sprint event?', 'Dans quelle ville Martin Fourcade a-t-il réalisé son premier top 10 en sprint lors d''une coupe du monde ?', '["Oslo", "Kontiolahti", "Pyeongchang", "Hochfilzen"]'::jsonb, '["Oslo", "Kontiolahti", "Pyeongchang", "Hochfilzen"]'::jsonb, 3, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-1285d38f45925848', 'In the 2011 World Cup general classification, Martin Fourcade finished ahead of Emil Hegle Svendsen.', 'Au classement général de la Coupe du monde 2011, Martin Fourcade a terminé devant Emil Hegle Svendsen.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-899f8e05c959fa55', 'At the 2011 World Championships in Khanty-Mansiysk, who did Martin Fourcade beat to win the pursuit gold medal?', 'Aux championnats du monde 2011 à Khanty-Mansiïsk, qui Martin Fourcade a-t-il battu pour remporter l''or en poursuite ?', '["Emil Hegle Svendsen and Tarjei Bø", "Christoph Sumann and Pavol Hurajt", "Arnd Peiffer and Simon Fourcade", "Vincent Jay and Vincent Defrasne"]'::jsonb, '["Emil Hegle Svendsen et Tarjei Bø", "Christoph Sumann et Pavol Hurajt", "Arnd Peiffer et Simon Fourcade", "Vincent Jay et Vincent Defrasne"]'::jsonb, 0, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b507cf90ef0e537e', 'During the 2012 World Championships pursuit, which Swedish biathlete was Martin Fourcade battling for the win?', 'Lors de la poursuite des championnats du monde 2012, quel biathlète suédois Martin Fourcade a-t-il dû distancer pour s''imposer ?', '["Fredrik Lindström", "Sebastian Samuelsson", "Carl Johan Bergman", "Björn Ferry"]'::jsonb, '["Fredrik Lindström", "Sebastian Samuelsson", "Carl Johan Bergman", "Björn Ferry"]'::jsonb, 2, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-75819850a8812b1f', 'Martin Fourcade qualified for the 2012-2013 cross-country skiing World Cup by finishing as the second-best Frenchman in Beitostølen.', 'Martin Fourcade s''est qualifié pour la coupe du monde de ski de fond 2012-2013 en terminant deuxième Français à Beitostølen.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-bb05ff0aaf3f140c', 'During the 2013 World Championships, Martin Fourcade won the Individual race after a sprint finish against Tim Burke.', 'Lors des championnats du monde 2013, Martin Fourcade a remporté l''Individuel après un sprint final contre Tim Burke.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-231a3f36e378b002', 'Which French biathlete competed in his final career event alongside Martin Fourcade in a relay in December 2012?', 'Quel biathlète français a disputé la dernière épreuve de sa carrière aux côtés de Martin Fourcade lors d''un relais en décembre 2012 ?', '["Alexis Bœuf", "Vincent Jay", "Jean-Guillaume Béatrix", "Simon Fourcade"]'::jsonb, '["Alexis Bœuf", "Vincent Jay", "Jean-Guillaume Béatrix", "Simon Fourcade"]'::jsonb, 1, 'Sports', 'hard', CURRENT_TIMESTAMP),
