    (gen_random_uuid()::text, 'gen-2cc794d6023cb652', 'Against which player did Rafael Nadal secure his very first professional victory in a Challenger tournament?', 'Contre quel joueur Rafael Nadal a-t-il remporté sa toute première victoire professionnelle dans un tournoi Challenger ?', '["Albert Montañés", "Israel Matos Gil", "Guillermo Platel-Varas", "Ramón Delgado"]'::jsonb, '["Albert Montañés", "Israel Matos Gil", "Guillermo Platel-Varas", "Ramón Delgado"]'::jsonb, 1, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d3b1e64a042ca142', 'Rafael Nadal''s family accepted the Spanish tennis federation''s request to move his training to Barcelona.', 'La famille de Rafael Nadal a accepté la demande de la fédération espagnole de tennis de déplacer son entraînement à Barcelone.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Sports', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b9f70bc605c0b382', 'Which injury forced Rafael Nadal to miss the French Open and Wimbledon in 2004?', 'Quelle blessure a contraint Rafael Nadal à manquer Roland-Garros et Wimbledon en 2004 ?', '["Chronic knee tendonitis", "Stress fracture in his left ankle", "Fractured right wrist", "Torn shoulder ligament"]'::jsonb, '["Tendinite chronique au genou", "Fracture de fatigue à la cheville gauche", "Fracture du poignet droit", "Déchirure d''un ligament de l''épaule"]'::jsonb, 1, 'Sports', 'hard', CURRENT_TIMESTAMP),
