    (gen_random_uuid()::text, 'gen-3f520641b896725c', 'During the Predynastic period, the Egyptian climate was much drier than it is today.', 'Durant la période prédynastique, le climat égyptien était beaucoup plus aride qu''aujourd''hui.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'History', 'hard', CURRENT_TIMESTAMP),
